use semio_framework_test_fixtures::fixture_text;
#[path="../../../../♻️retirement/🧪️tests/⏱️work/🦀️.rs"]mod close_work_policy;
use crate::retained_clone::retained_clone_grant_admits;
use super::*;
use crate::{DslValue,Number,ValueRefusalKind,list::persistent::PersistentList,native_decoding::owned::{NativeFlatRecord,NativeRecordField},retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement},shared_issuance::SealedShared};
#[derive(crate::RetireOwned)]#[value(crate="crate")]
struct Row{label:SealedShared<String>,rank:Number}
impl Clone for Row{fn clone(&self)->Self{panic!("persistent native receiving must never clone an owned typed row")}}
impl NativeFlatRecord<1,1> for Row{
 const TEXT_FIELDS:[NativeRecordField;1]=[NativeRecordField{name:"label",ordinal:0}];const NUMBER_FIELDS:[NativeRecordField;1]=[NativeRecordField{name:"rank",ordinal:1}];
 fn validation_demand(_: [&str;1],_: [Number;1])->RetirementDemand{RetirementDemand{copy_bytes:std::mem::size_of::<Number>()+std::mem::size_of::<usize>(),depth:1,..Default::default()}}
 fn validate_parts(_: [&str;1],numbers:[Number;1])->Result<(),ValueError>{if numbers[0].as_i64().is_some(){Ok(())}else{Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original row rank is not an exact integer"))}}
 fn from_parts([label]:[SealedShared<String>;1],[rank]:[Number;1])->Self{Self{label,rank}}
}
crate::native_flat_record_receive!(Row,1,1);
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){crate::observe_retirement_allocations(run)}
struct OriginalConstructionTurn{original:RetainedCloneGrant,granted:bool,accepted:bool}
impl crate::native_decoding::NativeDecodeConstructionRecipient for OriginalConstructionTurn{
 fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(!self.granted);assert!(crate::retained_clone::retained_clone_grant_admits(self.original,d));self.granted=true;Ok(self.original)}
 fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(self.granted&&!self.accepted);assert_eq!(g,self.original);assert!(p.fits(g));self.accepted=true;Ok(())}
}
pub(crate) fn receive<R>(control:&mut NativeDecodeControl<'_>,original:RetainedCloneGrant,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->Result<R,ValueError>)->Result<R,ValueError>{let mut recipient=OriginalConstructionTurn{original,granted:false,accepted:false};let result=control.with_construction_recipient(&mut recipient,operation);if result.is_ok(){assert_eq!(recipient.granted,recipient.accepted);}result}
fn account(p:RetainedCloneProgress,g:RetainedCloneGrant,h:(usize,usize),total:&mut(usize,usize)){assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));total.0+=h.0;total.1+=h.1;}
fn denied(d:RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{let g=grant(d);[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,g)|active.then_some(g))}
fn input(count:usize,prefix:&str,stride:i64,repeat:usize,bad:Option<usize>)->DslValue{DslValue::Array((0..count).map(|i|DslValue::Object(vec![("label".into(),DslValue::String(if i==0{prefix.repeat(repeat)}else{format!("{prefix}{i}")})),("rank".into(),if bad==Some(i){DslValue::String("refused".into())}else{DslValue::Number(Number::Int(i as i64*stride))})])).collect())}
fn source<I:RetireOwned+Sync>(value:I)->RetainedCloneSource<I>{let d=RetainedCloneSource::<I>::owned_constructor_demand::<()>();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:RetainedCloneSource::<I>::constructor_copy_bytes(),maximum_capacity_bytes:d.capacity_bytes,maximum_depth:d.depth,..Default::default()};RetainedCloneSource::admit_owned(value,(),g).unwrap_or_else(|_|panic!("original native persistent input source")).0}
fn close<T:RetireOwned>(value:T,total:&mut(usize,usize)){let(mut owner,h)=observe(||ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original persistent receiving retirement")));total.0+=h.0;total.1+=h.1;let mut close_work=close_work_policy::Work::new();while !owner.terminal_is_empty(){let d=owner.next_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let mut g=grant(d);g.maximum_copy_bytes=g.maximum_copy_bytes.max(4096);let(s,h)=observe(||owner.step(g).unwrap());account(s.progress(),g,h,total);let repeated=!owner.terminal_is_empty()&&owner.next_demand(4096).unwrap()==d;close_work.observe(s.progress()==Default::default()&&repeated);}assert_eq!(observe(||drop(owner)).1,(0,0));}
fn close_receiver(receiver:&mut NativePersistentListReceiver<DslValue,Row>,rows:usize,total:&mut(usize,usize)){receiver.begin_close();let mut close_work=close_work_policy::Work::for_rows(rows);while !receiver.terminal_is_empty(){let d=receiver.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");for g in denied(d){let(s,h)=observe(||receiver.close_step(g).unwrap());assert_eq!(h,(0,0));assert_eq!(s.progress(),Default::default());}let mut g=grant(d);g.maximum_copy_bytes=g.maximum_copy_bytes.max(4096);let(s,h)=observe(||receiver.close_step(g).unwrap());account(s.progress(),g,h,total);let repeated=!receiver.terminal_is_empty()&&receiver.close_demands(4096).unwrap()==d;close_work.observe(s.progress()==Default::default()&&repeated);}}

/// 🧳️ Actual typed field receiving streams original children into persistent pages with exact grants and cancellation.
#[test]
fn native_persistent_list_receives_original_rows_and_preserves_all_cancelled_custody(){
 let f:serde_json::Value=serde_json::from_str(fixture_text!("../../📋️list/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let prefix=f["prefix"].as_str().unwrap();let stride=f["stride"].as_i64().unwrap();let repeat=f["firstRepeat"].as_u64().unwrap()as usize;
 for count in f["cases"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;for cut in std::iter::once(None).chain(f["cuts"].as_array().unwrap().iter().map(|c|Some(c.as_u64().unwrap()as usize))){
  let((original,foreign),mut total)=observe(||(source(input(count,prefix,stride,repeat,None)),source(input(count,prefix,stride,repeat,None))));let original_pointer=std::ptr::from_ref(original.borrow().get());let expected=serde_json::Value::from(original.borrow().get());let d=<PersistentList<Row>as NativeReceive<DslValue>>::receive_birth_demand();for g in denied(d){let(result,h)=observe(||<PersistentList<Row>as NativeReceive<DslValue>>::begin_receive(g));assert!(result.is_err());assert_eq!(h,(0,0));}let(mut receiver,p)=<PersistentList<Row>as NativeReceive<DslValue>>::begin_receive(grant(d)).unwrap();assert!(p.fits(grant(d)));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;let mut turns=0;let mut prepared_birth=0;let mut output=None;let mut work=close_work_policy::Work::for_rows(count);
  while !receiver.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=receiver.demands(original.borrow(),512).unwrap();if turns>0{assert!(receiver.demands(foreign.borrow(),512).is_err());}for g in denied(d){let(s,h)=observe(||receive(&mut control,g,|control|receiver.advance(original.borrow(),control,512,g)).unwrap());assert_eq!(h,(0,0));assert_eq!(s.progress(),Default::default());assert_eq!(receiver.demands(original.borrow(),512).unwrap(),d);}let g=grant(d);let(s,h)=observe(||receive(&mut control,g,|control|receiver.advance(original.borrow(),control,512,g)).unwrap());account(s.progress(),g,h,&mut total);prepared_birth+=h.0;assert_eq!(control.owned_bytes(),prepared_birth);assert_eq!(std::ptr::from_ref(original.borrow().get()),original_pointer);turns+=1;work.observe(s.progress()==Default::default()&&!receiver.output_ready()&&receiver.demands(original.borrow(),512).unwrap()==d);}
  if cut.is_none(){let d=receiver.take_demand().unwrap();for g in denied(d){let(result,h)=observe(||receiver.take(g).unwrap());assert!(result.is_none());assert_eq!(h,(0,0));}let g=grant(d);let((root,p),h)=observe(||receiver.take(g).unwrap().unwrap());account(p,g,h,&mut total);assert_eq!(root.len(),count);let actual:Vec<_>=(0..count).map(|i|{let row=root.get(i).unwrap();serde_json::json!({"label":row.label.as_str(),"rank":row.rank.as_i64().unwrap()})}).collect();assert_eq!(serde_json::Value::Array(actual),expected);output=Some(root);}
  close_receiver(&mut receiver,count,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(foreign,&mut total);close(original,&mut total);if let Some(root)=output{for i in 0..count{assert_eq!(root.get(i).unwrap().rank.as_i64(),Some(i as i64*stride));}close(root,&mut total);}assert_eq!(total.0,total.1);eprintln!("[DEBUG] original native persistent receiving rows={count} cut={cut:?} receivingTurns={turns} originalInputPointer=true childRowsClone=0 temporaryOutputVector=0 decoderLedger={prepared_birth} physicalBirth={} physicalRelease={} deniedAxes=5 terminalDrop=0",total.0,total.1);
 }}
}

/// 🚧️ Invalid later rows retain original input and all previously received native page owners.
#[test]
fn native_persistent_list_later_row_refusal_retains_original_partial_owner(){
 let f:serde_json::Value=serde_json::from_str(fixture_text!("../../📋️list/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for bad in f["invalidRows"].as_array().unwrap(){let bad=bad.as_u64().unwrap()as usize;let(original,mut total)=observe(||source(input(257,"α🙂",2,1,Some(bad))));let before=serde_json::Value::from(original.borrow().get());let d=<PersistentList<Row>as NativeReceive<DslValue>>::receive_birth_demand();let(mut receiver,_)=<PersistentList<Row>as NativeReceive<DslValue>>::begin_receive(grant(d)).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;let mut refused=false;let mut work=close_work_policy::Work::for_rows(257);while !receiver.output_ready(){let d=receiver.demands(original.borrow(),512).unwrap();let g=grant(d);let(result,h)=observe(||receive(&mut control,g,|control|receiver.advance(original.borrow(),control,512,g)));match result{Ok(s)=>{account(s.progress(),g,h,&mut total);let repeated=!receiver.output_ready()&&receiver.demands(original.borrow(),512).unwrap()==d;work.observe(s.progress()==Default::default()&&repeated);},Err(error)=>{account(error.retained_progress(),g,h,&mut total);assert_eq!(error.kind,ValueRefusalKind::InvalidValue);refused=true;break;}}}assert!(refused);assert_eq!(serde_json::Value::from(original.borrow().get()),before);close_receiver(&mut receiver,257,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(original,&mut total);assert_eq!(total.0,total.1);eprintln!("[DEBUG] original native persistent refused row={bad} input preserved, partial page custody closed, physicalBirth={} physicalRelease={} terminalDrop=0",total.0,total.1);}
}

/// ⏹️ Original cancellation happens before a construction turn and leaves every previously born owner available to funded closure.
#[test]
fn native_persistent_list_original_callback_refusal_preserves_partial_receiving(){
 for allow in[0usize,1,3,8,31,256]{let(original,mut total)=observe(||source(input(17,"α🙂",2,10923,None)));let before=serde_json::Value::from(original.borrow().get());let d=<PersistentList<Row>as NativeReceive<DslValue>>::receive_birth_demand();let(mut receiver,_)=<PersistentList<Row>as NativeReceive<DslValue>>::begin_receive(grant(d)).unwrap();let calls=std::cell::Cell::new(0usize);let mut callback=|_|{let call=calls.get();calls.set(call+1);call<allow};let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;let mut stopped=false;let mut work=close_work_policy::Work::for_rows(17);
  while !receiver.output_ready(){let d=receiver.demands(original.borrow(),512).unwrap();let g=grant(d);let(result,h)=observe(||receive(&mut control,g,|control|receiver.advance(original.borrow(),control,512,g)));match result{Ok(s)=>{account(s.progress(),g,h,&mut total);work.observe(s.progress()==Default::default()&&!receiver.output_ready()&&receiver.demands(original.borrow(),512).unwrap()==d);},Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::Canceled);account(error.retained_progress(),g,h,&mut total);stopped=true;break;}}}assert!(stopped);assert_eq!(serde_json::Value::from(original.borrow().get()),before);close_receiver(&mut receiver,17,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(original,&mut total);assert_eq!(total.0,total.1);eprintln!("[DEBUG] original persistent decode callback allow={allow}, original input and partial ownership preserved; physicalBirth={} physicalRelease={} terminalDrop=0",total.0,total.1);
 }
}

/// 🎮️ Every native receiving and page-construction action respects the original interaction quantum and funded work span.
#[test]
fn native_persistent_list_receiving_fits_original_interaction_quantum(){
 let f:serde_json::Value=serde_json::from_str(fixture_text!("../../📋️list/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["bodyReservations"].as_array().unwrap(){assert_eq!(super::receiving_child_body_budget(row["bodyBytes"].as_u64().unwrap()as usize,row["metadataBytes"].as_u64().unwrap()as usize),row["childBytes"].as_u64().unwrap()as usize);}let q=&f["interactionQuantum"];let copy=q["copyBytes"].as_u64().unwrap()as usize;let items=q["workItems"].as_u64().unwrap()as usize;let maximum=q["maximumTurns"].as_u64().unwrap()as usize;let(original,mut total)=observe(||source(input(17,"α🙂",2,10923,None)));let fund=|d:RetirementDemand|{assert!(d.copy_bytes<=copy,"original native persistent receiving quote{} exceeds responsive quantum{copy}",d.copy_bytes);RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}};let d=<PersistentList<Row>as NativeReceive<DslValue>>::receive_birth_demand();let(mut receiver,p)=<PersistentList<Row>as NativeReceive<DslValue>>::begin_receive(fund(d)).unwrap();assert!(p.fits(fund(d)));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;let mut turns=0;let mut born=0;
 while !receiver.output_ready(){let d=receiver.demands(original.borrow(),copy).unwrap();let g=fund(d);let(s,h)=observe(||receive(&mut control,g,|control|receiver.advance(original.borrow(),control,copy,g)).unwrap());account(s.progress(),g,h,&mut total);born+=h.0;assert_eq!(control.owned_bytes(),born);turns+=1;assert!(turns<=maximum,"original wide persistent receiving exceeded its authored funded throughput bound");}let d=receiver.take_demand().unwrap();let g=fund(d);let((root,p),h)=observe(||receiver.take(g).unwrap().unwrap());account(p,g,h,&mut total);assert_eq!(root.len(),17);assert_eq!(root.get(0).unwrap().label.as_str(),"α🙂".repeat(10923));close_receiver(&mut receiver,17,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(original,&mut total);close(root,&mut total);assert_eq!(total.0,total.1);eprintln!("[DEBUG] original persistent receiving responsive copyQuantum={copy} workItems={items} receivingTurns={turns} <={maximum}, wideUTF8=65538, originalDecoderLedger={born}, physicalBirth={} physicalRelease={} terminalDrop=0",total.0,total.1);
}

/// 🪪️ An actual original Vec provider keeps its typed receiver and parsed source until funded output handoff and closure.
#[test]
fn native_persistent_list_original_vector_owner_fits_quantum_and_keeps_custody(){
 type Owner=crate::native_decoding::owned::NativeReceivingOriginal<Vec<DslValue>,PersistentList<Row>>;let f:serde_json::Value=serde_json::from_str(fixture_text!("../../📋️list/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let copy=f["interactionQuantum"]["copyBytes"].as_u64().unwrap()as usize;let items=f["interactionQuantum"]["workItems"].as_u64().unwrap()as usize;
 for cut in std::iter::once(None).chain(f["ownedWrapperCuts"].as_array().unwrap().iter().map(|c|Some(c.as_u64().unwrap()as usize))){let(mut original,mut total)=observe(||{let DslValue::Array(rows)=input(17,"α🙂",2,1,None)else{unreachable!()};Some(source(rows))});let pointer=std::ptr::from_ref(original.as_ref().unwrap().borrow().get());let fund=|d:RetirementDemand|{assert!(d.copy_bytes<=copy,"original vector receiving wrapper quote{} exceeds responsive quantum{copy}",d.copy_bytes);RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}};let d=Owner::shell_demand();let(mut owner,p)=Owner::begin_shell(fund(d)).unwrap();assert!(p.fits(fund(d)));let g=fund(owner.original_capture_demand().unwrap());let(p,h)=observe(||owner.admit_original(&mut original,g).unwrap());account(p,g,h,&mut total);assert!(original.is_none());assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),pointer);let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;let d=owner.receiver_birth_demand().unwrap();let g=fund(d);control.charge(d.capacity_bytes).unwrap();let(p,h)=observe(||owner.begin_receiver(g).unwrap());account(p,g,h,&mut total);let mut prepared=h.0;assert_eq!(control.owned_bytes(),prepared);let mut turns=0;let mut output=None;let mut work=close_work_policy::Work::for_rows(17);
  while !owner.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=owner.demands(copy).unwrap();let g=fund(d);let(s,h)=observe(||receive(&mut control,g,|control|owner.advance(control,copy,g)).unwrap());account(s.progress(),g,h,&mut total);prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),pointer);turns+=1;work.observe(s.progress()==Default::default()&&!owner.output_ready()&&owner.demands(copy).unwrap()==d);}if cut.is_none(){let g=fund(owner.take_demand().unwrap());let((root,p),h)=observe(||owner.take(g).unwrap().unwrap());account(p,g,h,&mut total);assert_eq!(root.len(),17);for i in 0..17{assert_eq!(root.get(i).unwrap().rank.as_i64(),Some(i as i64*2));}output=Some(root);}owner.begin_close();let mut close_work=close_work_policy::Work::for_rows(17);while !owner.terminal_is_empty(){let d=owner.close_demands(copy).unwrap();let g=fund(d);control.charge(d.capacity_bytes).unwrap();let(s,h)=observe(||owner.close_step(g).unwrap());account(s.progress(),g,h,&mut total);prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);close_work.observe(s.progress()==Default::default()&&!owner.terminal_is_empty()&&owner.close_demands(copy).unwrap()==d);}assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(root)=output{close(root,&mut total);}assert_eq!(total.0,total.1);eprintln!("[DEBUG] original Vec native persistent owner cut={cut:?}, quantum={copy}, originalInputPointer=true receivingTurns={turns}, physicalBirth={} physicalRelease={} terminalDrop=0",total.0,total.1);
 }
}
